pub fn havoc_inline_post(v: &mut Vec<u32>, a: u32, b: bool) {
    // Assumptions from the problem statement:
    // - v may be empty; if non-empty, all elements are initially 1
    // - 10 < a < 20
    // - b == false

    // Modify in place: add `a` to each element.
    // Under the assumptions, each element becomes 1 + a and fits in u32.
    for x in v.iter_mut() {
        *x = x.wrapping_add(a);
    }

    // These are postcondition facts given the assumptions; assert them in debug builds.
    debug_assert!(a > 10 && a < 20);
    debug_assert!(2 * a > 20 && 2 * a < 40);
    debug_assert!(!b);

    for &x in v.iter() {
        debug_assert!(x == 1u32 + a);
    }
}